changeSet.sql:
-- Ajout de bon_livraison_client_id dans documents_comptables
ALTER TABLE IF EXISTS documents_comptables 
    ADD COLUMN IF NOT EXISTS bon_livraison_client_id BIGINT;

-- Index pour les recherches instantanées des pièces jointes BL Client
CREATE INDEX IF NOT EXISTS idx_documents_comptables_bl_client ON documents_comptables(bon_livraison_client_id);
